                      "content": "// Reference implementation: packages/registry/default/ui/switch/switch.marko\n// Guide: /docs/creating-components · Authoring rules: v2 pattern\nimport * as avatarMachine from \"@zag-js/avatar\";\nimport type { MachineInput } from \"marko-ui\";\nimport { cn } from \"../../../lib/utils.ts\";\n\nexport type Input = MachineInput<\"span\", avatarMachine.Props> & {\n  src?: string;\n  alt?: string;\n  fallback?: string;\n  content?: Marko.Body;\n  statusChange?: (status: avatarMachine.LoadStatus) => void;\n};\n\n// The three-tag wiring (see /docs/creating-components):\n// 1. <machine-props> picks the machine's props out of `input` by name and\n//    merges the attributes written on it — callback adaptations live HERE,\n//    visibly, because they are this component's public contract.\n// 2. <service> creates and owns the running machine (client-only; SSR\n//    renders from a throwaway never-started instance).\n// 3. <connect> returns `api` as a GETTER — call it at every use site.\n//    Getters are the serializable currency of Marko's resumability: the\n//    api object itself must never become reactive state.\n<machine-props/machineProps from=input pick=avatarMachine.props\n  onStatusChange(details: avatarMachine.StatusChangeDetails) {\n    input.onStatusChange?.(details);\n    input.statusChange?.(details.status);\n  }/>\n<service/service machine=() => avatarMachine.machine props=machineProps/>\n<connect/api=(service, normalizeProps) =>\n  avatarMachine.connect(service, normalizeProps)\n  service=service\n/>\n\n// Whatever is neither machine-owned (splitProps) nor component-owned\n// (class, src, alt, fallback, content, statusChange) passes through to the\n// root span: aria-*, data-*...\n<const/nativeAttrs=() => {\n  const {\n    class: ownClass,\n    src: ownSrc,\n    alt: ownAlt,\n    fallback: ownFallback,\n    content: ownContent,\n    statusChange: ownChangeHandler,\n    ...native\n  } = avatarMachine.splitProps(input)[1];\n  return native;\n}>\n\n<span\n  ...nativeAttrs()\n  ...api().getRootProps()\n  data-slot=\"avatar\"\n  class=cn(\"relative flex size-8 shrink-0 overflow-hidden rounded-full\", input.class)\n>\n  <if=input.src>\n    <img\n      ...api().getImageProps()\n      src=input.src\n      alt=input.alt\n      data-slot=\"avatar-image\"\n      class=\"aspect-square size-full\"\n    />\n  </if>\n  <span\n    ...api().getFallbackProps()\n    data-slot=\"avatar-fallback\"\n    class=\"bg-muted flex size-full items-center justify-center rounded-full\"\n  >\n    <if=input.content>\n      <${input.content}/>\n    </if>\n    <else>\n      ${input.fallback}\n    </else>\n  </span>\n</span>\n\n// Parents can receive the api getter: <Avatar/avatarApi/> then\n// `avatarApi().loaded` — it stays live across machine updates.\n<return=api>\n"
