      "breadcrumb-separator": { component: Demo_breadcrumb_breadcrumb_separator, source: "import Breadcrumb from \"@marko-ui/registry/ui/breadcrumb/breadcrumb.marko\";\nimport BreadcrumbItem from \"@marko-ui/registry/ui/breadcrumb/item.marko\";\nimport BreadcrumbLink from \"@marko-ui/registry/ui/breadcrumb/link.marko\";\nimport BreadcrumbPage from \"@marko-ui/registry/ui/breadcrumb/page.marko\";\nimport BreadcrumbSeparator from \"@marko-ui/registry/ui/breadcrumb/separator.marko\";\n\n<Breadcrumb>\n  <BreadcrumbItem>\n    <BreadcrumbLink href=\"/\">Home</BreadcrumbLink>\n  </BreadcrumbItem>\n  <BreadcrumbSeparator>\n    <span>&rsaquo;</span>\n  </BreadcrumbSeparator>\n  <BreadcrumbItem>\n    <BreadcrumbLink href=\"/docs\">Docs</BreadcrumbLink>\n  </BreadcrumbItem>\n  <BreadcrumbSeparator>\n    <span>&rsaquo;</span>\n  </BreadcrumbSeparator>\n  <BreadcrumbItem>\n    <BreadcrumbPage>Installation</BreadcrumbPage>\n  </BreadcrumbItem>\n</Breadcrumb>" },
