      "content-only": { component: Demo_card_content_only, source: "import Card from \"@marko-ui/registry/ui/card/card.marko\";\nimport CardContent from \"@marko-ui/registry/ui/card/content.marko\";\n\n<Card class=\"w-full max-w-sm\">\n  <CardContent>\n    <p>A minimal card with only content, no header or footer.</p>\n  </CardContent>\n</Card>" },
      "default": { component: Demo_card_default, source: "import Card from \"@marko-ui/registry/ui/card/card.marko\";\nimport CardHeader from \"@marko-ui/registry/ui/card/header.marko\";\nimport CardTitle from \"@marko-ui/registry/ui/card/title.marko\";\nimport CardDescription from \"@marko-ui/registry/ui/card/description.marko\";\nimport CardAction from \"@marko-ui/registry/ui/card/action.marko\";\nimport CardContent from \"@marko-ui/registry/ui/card/content.marko\";\nimport CardFooter from \"@marko-ui/registry/ui/card/footer.marko\";\nimport Button from \"@marko-ui/registry/ui/button/button.marko\";\nimport Input from \"@marko-ui/registry/ui/input/input.marko\";\nimport Label from \"@marko-ui/registry/ui/label/label.marko\";\n\n<Card class=\"w-full max-w-sm\">\n  <CardHeader>\n    <CardTitle>Login to your account</CardTitle>\n    <CardDescription>Enter your email below to login to your account</CardDescription>\n    <CardAction>\n      <Button variant=\"link\">Sign Up</Button>\n    </CardAction>\n  </CardHeader>\n  <CardContent>\n    <div class=\"flex flex-col gap-6\">\n      <div class=\"grid gap-2\">\n        <Label for=\"card-demo-email\">Email</Label>\n        <Input id=\"card-demo-email\" type=\"email\" placeholder=\"m@example.com\" required/>\n      </div>\n      <div class=\"grid gap-2\">\n        <div class=\"flex items-center\">\n          <Label for=\"card-demo-password\">Password</Label>\n          <a href=\"#\" class=\"ml-auto inline-block text-sm underline-offset-4 hover:underline\">\n            Forgot your password?\n          </a>\n        </div>\n        <Input id=\"card-demo-password\" type=\"password\" required/>\n      </div>\n    </div>\n  </CardContent>\n  <CardFooter class=\"flex-col gap-2\">\n    <Button type=\"submit\" class=\"w-full\">Login</Button>\n    <Button variant=\"outline\" class=\"w-full\">Login with Google</Button>\n  </CardFooter>\n</Card>" },
      "full-composition": { component: Demo_card_full_composition, source: "import Card from \"@marko-ui/registry/ui/card/card.marko\";\nimport CardHeader from \"@marko-ui/registry/ui/card/header.marko\";\nimport CardTitle from \"@marko-ui/registry/ui/card/title.marko\";\nimport CardDescription from \"@marko-ui/registry/ui/card/description.marko\";\nimport CardAction from \"@marko-ui/registry/ui/card/action.marko\";\nimport CardContent from \"@marko-ui/registry/ui/card/content.marko\";\nimport CardFooter from \"@marko-ui/registry/ui/card/footer.marko\";\nimport Button from \"@marko-ui/registry/ui/button/button.marko\";\n\n<Card class=\"w-full max-w-sm\">\n  <CardHeader>\n    <CardTitle>Card Title</CardTitle>\n    <CardDescription>Card Description</CardDescription>\n    <CardAction>\n      <Button variant=\"ghost\" size=\"sm\">Card Action</Button>\n    </CardAction>\n  </CardHeader>\n  <CardContent>\n    <p>Card Content</p>\n  </CardContent>\n  <CardFooter>\n    <p>Card Footer</p>\n  </CardFooter>\n</Card>" },
