  "input-otp": {
    docs: docs_input_otp,
    registry: {
          "title": "Input OTP",
          "description": "Accessible one-time password component with copy paste functionality.",
          "dependencies": [
                "@zag-js/pin-input",
                "marko-ui"
          ],
          "files": [
                {
                      "path": "src/components/ui/input-otp/input-otp.marko",
                      "content": "import * as pinInputMachine from \"@zag-js/pin-input\";\nimport type { MachineInput } from \"marko-ui\";\nimport { cn } from \"../../../lib/utils.ts\";\n\n// MachineInput = native <div> attributes ∩ the machine's full Props, with\n// `id` made optional (generated below, overridable). `valueChange` and\n// `valueCompleteChange` are additive sugar enabling Marko's two-way bind\n// shorthand; Zag's own `onValueChange`/`onValueComplete` also work and\n// receive the details object.\nexport type Input = MachineInput<\"div\", pinInputMachine.PinInputProps> & {\n  valueChange?: (value: string[]) => void;\n  valueCompleteChange?: (value: string[]) => void;\n  groupSize?: number;\n  // Sugar alias for the machine's `count` prop.\n  length?: number;\n};\n\n<machine-props/machineProps from=input pick=pinInputMachine.props\n  count=input.count ?? input.length\n  onValueChange(details: pinInputMachine.ValueChangeDetails) {\n    input.onValueChange?.(details);\n    input.valueChange?.(details.value);\n  }\n  onValueComplete(details: pinInputMachine.ValueChangeDetails) {\n    input.onValueComplete?.(details);\n    input.valueCompleteChange?.(details.value);\n  }/>\n<service/service machine=() => pinInputMachine.machine props=machineProps/>\n<connect/api=(service, normalizeProps) =>\n  pinInputMachine.connect(service, normalizeProps)\n  service=service\n/>\n\n// Whatever is neither machine-owned (splitProps) nor component-owned\n// (class, valueChange, valueCompleteChange, groupSize, length) passes\n// through to the root div: aria-*, data-*, form attributes...\n<const/nativeAttrs=() => {\n  const {\n    class: ownClass,\n    valueChange: ownValueChangeHandler,\n    valueCompleteChange: ownValueCompleteChangeHandler,\n    groupSize: ownGroupSize,\n    length: ownLength,\n    ...native\n  } = pinInputMachine.splitProps(input)[1];\n  return native;\n}>\n\n<div\n  ...nativeAttrs()\n  ...api().getRootProps()\n  data-slot=\"input-otp\"\n  class=cn(\"flex items-center gap-2 has-disabled:opacity-50\", input.class)\n>\n  <input ...api().getHiddenInputProps()>\n  <for|index| of=api().items>\n    <if=(input.groupSize && index > 0 && index % input.groupSize === 0)>\n      <div data-slot=\"input-otp-separator\" class=\"text-muted-foreground\">-</div>\n    </if>\n    <input\n      ...api().getInputProps({ index })\n      data-slot=\"input-otp-slot\"\n      class=\"border-input size-9 rounded-md border text-center text-sm shadow-xs outline-none focus:ring-[3px] focus:ring-ring/50 focus:border-ring\"\n    />\n  </for>\n</div>\n\n// Parents can receive the api getter: <InputOtp/inputOtpApi/> then\n// `inputOtpApi().value` — it stays live across machine updates.\n<return=api>\n"
                }
          ]
    },
    demos: {
      "input-otp-controlled": { component: Demo_input_otp_input_otp_controlled, source: "import InputOTP from \"@marko-ui/registry/ui/input-otp/input-otp.marko\";\n\n<let/value=[\"1\", \"2\", \"3\", \"\", \"\", \"\"]/>\n\n<div class=\"space-y-2\">\n  <InputOTP\n    length=6\n    value=value\n    valueChange(next) { value = next; }\n  />\n  <p class=\"text-sm text-muted-foreground\">Value: ${value.join(\"\")}</p>\n</div>" },
      "input-otp-demo": { component: Demo_input_otp_input_otp_demo, source: "import InputOTP from \"@marko-ui/registry/ui/input-otp/input-otp.marko\";\n\n<InputOTP length=6/>" },
      "input-otp-disabled": { component: Demo_input_otp_input_otp_disabled, source: "import InputOTP from \"@marko-ui/registry/ui/input-otp/input-otp.marko\";\n\n<InputOTP length=6 disabled/>" },
      "input-otp-masked": { component: Demo_input_otp_input_otp_masked, source: "import InputOTP from \"@marko-ui/registry/ui/input-otp/input-otp.marko\";\n\n<InputOTP length=6 mask/>" },
      "input-otp-separator": { component: Demo_input_otp_input_otp_separator, source: "import InputOTP from \"@marko-ui/registry/ui/input-otp/input-otp.marko\";\n\n<InputOTP length=6 groupSize=3/>" },
    },
  },
