                      "content": "import { cn } from \"../../../lib/utils.ts\";\n\nexport interface Input extends Marko.Input<\"div\"> {}\n\n<const/{ class: className, content, ...rest }=input/>\n\n<div ...rest data-slot=\"item-separator\" role=\"separator\" class=cn(\"bg-border my-0 h-px w-full\", className)>\n  <${content}/>\n</div>\n"
