                      "content": "import * as sliderMachine from \"@zag-js/slider\";\nimport type { MachineInput } from \"marko-ui\";\nimport { cn } from \"../../../lib/utils.ts\";\n\nexport type Input = MachineInput<\"div\", sliderMachine.Props> & {\n  valueChange?: (value: number[]) => void;\n};\n\n<machine-props/machineProps from=input pick=sliderMachine.props\n  onValueChange(details: sliderMachine.ValueChangeDetails) {\n    input.onValueChange?.(details);\n    input.valueChange?.(details.value);\n  }/>\n<service/service machine=() => sliderMachine.machine props=machineProps/>\n<connect/api=(service, normalizeProps) =>\n  sliderMachine.connect(service, normalizeProps)\n  service=service\n/>\n\n<const/nativeAttrs=() => {\n  const {\n    class: ownClass,\n    valueChange: ownChangeHandler,\n    ...native\n  } = sliderMachine.splitProps(input)[1];\n  return native;\n}>\n\n<div\n  ...nativeAttrs()\n  ...api().getRootProps()\n  data-slot=\"slider\"\n  class=cn(\"relative flex w-full touch-none items-center select-none\", input.class)\n>\n  <div ...api().getControlProps() data-slot=\"slider-control\" class=\"relative flex grow touch-none items-center select-none\">\n    <div ...api().getTrackProps() data-slot=\"slider-track\" class=\"bg-muted relative grow rounded-full h-1.5 w-full\">\n      <div ...api().getRangeProps() data-slot=\"slider-range\" class=\"bg-primary absolute h-full\"></div>\n    </div>\n    <for|_, i| of=api().value>\n      <input ...api().getHiddenInputProps({ index: i })>\n      <div ...api().getThumbProps({ index: i }) data-slot=\"slider-thumb\" class=\"size-4 rounded-full border-primary bg-background border shadow-sm block shrink-0\"></div>\n    </for>\n  </div>\n</div>\n\n<return=api>\n"
