                      "content": "import { cn } from \"../../../lib/utils.ts\";\n\nexport interface Input extends Marko.Input<\"svg\"> {}\n\n<const/{ class: className, ...rest }=input/>\n\n<svg\n  ...rest\n  data-slot=\"spinner\"\n  role=\"status\"\n  aria-label=\"Loading\"\n  xmlns=\"http://www.w3.org/2000/svg\"\n  width=\"24\"\n  height=\"24\"\n  viewBox=\"0 0 24 24\"\n  fill=\"none\"\n  stroke=\"currentColor\"\n  stroke-width=\"2\"\n  stroke-linecap=\"round\"\n  stroke-linejoin=\"round\"\n  class=cn(\"size-4 animate-spin text-muted-foreground\", className)\n>\n  <path d=\"M21 12a9 9 0 1 1-6.219-8.56\"/>\n</svg>\n"
